r_","type":"address"},{"internalType":"address","name":"","type":"address"}],"name":"notifyLockerOwnerChange","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"owner","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"positionManager_","type":"address"}],"name":"positionManagerKind","outputs":[{"internalType":"enum ITitanLockerManagerV2.LockKind","name":"kind","type":"uint8"},{"internalType":"bool","name":"allowed","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"bool","name":"value_","type":"bool"}],"name":"setCreationEnabled","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"value_","type":"uint256"}],"name":"setEthFee","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"account_","type":"address"},{"internalType":"bool","name":"exempt_","type":"bool"}],"name":"setFeeExempt","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address payable","name":"value_","type":"address"}],"name":"setFeeReceiver","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"positionManager_","type":"address"},{"internalType":"enum ITitanLockerManagerV2.LockKind","name":"kind_","type":"uint8"},{"internalType":"bool","name":"allowed_","type":"bool"}],"name":"setPositionManager","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint16","name":"value_","type":"uint16"}],"name":"setTokenFeeBps","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"tokenFeeBps","outputs":[{"internalType":"uint16","name":"","type":"uint16"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"tokenLockerCount","outputs":[{"internalType":"uint40","na